from copy import deepcopy
from collections.abc import Iterable, Mapping


class RecordBoard:
    def __init__(self, records=None):
        self._records = []
        if records is None:
            return
        if isinstance(records, (str, bytes)) or not isinstance(records, Iterable):
            raise TypeError("records must be an iterable of mappings")
        for record in records:
            if not isinstance(record, Mapping):
                raise TypeError("each record must be a mapping")
            if "label" not in record:
                raise KeyError("label")
            label = record["label"]
            icon = record.get("icon")
            self._validate(label, icon)
            self._records.append({"label": deepcopy(label), "icon": deepcopy(icon), "marked": False})

    @staticmethod
    def _validate(label, icon):
        if not isinstance(label, str):
            raise TypeError("label must be a string")
        if not label:
            raise ValueError("label must not be empty")
        if icon is not None and not isinstance(icon, str):
            raise TypeError("icon must be a string or None")

    def add(self, label, icon=None):
        self._validate(label, icon)
        self._records.append({"label": deepcopy(label), "icon": deepcopy(icon), "marked": False})
        return len(self._records) - 1

    def set_marked(self, index, marked=True):
        if isinstance(index, bool) or not isinstance(index, int):
            raise TypeError("index must be an integer")
        if not isinstance(marked, bool):
            raise TypeError("marked must be a boolean")
        if index < 0 or index >= len(self._records):
            raise IndexError("record index out of range")
        self._records[index]["marked"] = marked

    def rows(self):
        return list(self._records)

    def marked_indices(self):
        return tuple(i for i, record in enumerate(self._records) if record["marked"])

